-- ═══ Part B: security ═══
-- Hand-written. Keep packages/db/test/security-invariants.test.ts and audience-rls.test.ts green.

-- ─── 1. Domain integrity ─────────────────────────────────────────────────────────────────────────────────────
ALTER TABLE "contacts" ADD CONSTRAINT contacts_subscription_type_chk CHECK (subscription_type IN ('marketing', 'non_marketing', 'unsubscribed'));
ALTER TABLE "contacts" ADD CONSTRAINT contacts_unsubscribed_by_chk CHECK (unsubscribed_by IS NULL OR unsubscribed_by IN ('contact', 'user', 'system'));
ALTER TABLE "contacts" ADD CONSTRAINT contacts_source_chk CHECK (source IN ('manual', 'import', 'api', 'form'));
ALTER TABLE "contacts" ADD CONSTRAINT contacts_custom_fields_object_chk CHECK (jsonb_typeof(custom_fields) = 'object');
ALTER TABLE "contact_identities" ADD CONSTRAINT contact_identities_kind_chk CHECK (kind IN ('email', 'phone', 'whatsapp', 'external'));
ALTER TABLE "contact_identities" ADD CONSTRAINT contact_identities_provider_chk CHECK ((kind = 'external') = (provider <> ''));
ALTER TABLE "custom_field_definitions" ADD CONSTRAINT custom_fields_type_chk CHECK (type IN ('text', 'long_text', 'number', 'decimal', 'boolean', 'date', 'datetime', 'email', 'phone', 'url', 'single_select', 'multi_select'));
ALTER TABLE "custom_field_definitions" ADD CONSTRAINT custom_fields_status_chk CHECK (status IN ('active', 'archived'));
ALTER TABLE "custom_field_definitions" ADD CONSTRAINT custom_fields_key_chk CHECK (key ~ '^[a-z][a-z0-9_]{1,39}$');
ALTER TABLE "custom_field_definitions" ADD CONSTRAINT custom_fields_archived_not_required_chk CHECK (NOT (status = 'archived' AND required));
ALTER TABLE "lists" ADD CONSTRAINT lists_status_chk CHECK (status IN ('active', 'archived'));
ALTER TABLE "lists" ADD CONSTRAINT lists_name_key_chk CHECK ((deleted_at IS NULL) = (name_key IS NOT NULL));
ALTER TABLE "tags" ADD CONSTRAINT tags_name_key_chk CHECK ((deleted_at IS NULL) = (name_key IS NOT NULL));
ALTER TABLE "list_memberships" ADD CONSTRAINT list_memberships_source_chk CHECK (source IN ('manual', 'import', 'api', 'bulk'));
ALTER TABLE "topics" ADD CONSTRAINT topics_kind_chk CHECK (kind IN ('topic', 'category'));
ALTER TABLE "topics" ADD CONSTRAINT topics_status_chk CHECK (status IN ('active', 'archived'));
ALTER TABLE "topics" ADD CONSTRAINT topics_key_chk CHECK (key ~ '^[a-z][a-z0-9_]{1,39}$');
ALTER TABLE "topics" ADD CONSTRAINT topics_default_is_topic_chk CHECK (NOT is_default OR (kind = 'topic' AND status = 'active'));
ALTER TABLE "contact_topic_preferences" ADD CONSTRAINT topic_prefs_status_chk CHECK (status IN ('subscribed', 'unsubscribed'));
ALTER TABLE "contact_topic_preferences" ADD CONSTRAINT topic_prefs_changed_by_chk CHECK (changed_by IN ('contact', 'user', 'system'));
ALTER TABLE "consent_events" ADD CONSTRAINT consent_events_action_chk CHECK (action IN ('subscribed', 'unsubscribed', 'pending', 'confirmed', 'revoked'));
ALTER TABLE "consent_events" ADD CONSTRAINT consent_events_channel_chk CHECK (channel IS NULL OR channel IN ('email', 'sms', 'whatsapp'));
-- Exactly one scope: a channel (consent) or a topic (preference).
ALTER TABLE "consent_events" ADD CONSTRAINT consent_events_scope_chk CHECK ((channel IS NULL) <> (topic_id IS NULL));
ALTER TABLE "consent_events" ADD CONSTRAINT consent_events_actor_chk CHECK (actor_type IN ('contact', 'user', 'system', 'api_key'));
ALTER TABLE "consent_events" ADD CONSTRAINT consent_events_basis_chk CHECK (lawful_basis IS NULL OR lawful_basis IN ('consent', 'contract', 'legal_obligation', 'vital_interests', 'public_task', 'legitimate_interests'));
ALTER TABLE "consent_events" ADD CONSTRAINT consent_events_states_chk CHECK (
  previous_state IN ('none', 'pending', 'granted', 'withdrawn', 'subscribed', 'unsubscribed')
  AND new_state IN ('pending', 'granted', 'withdrawn', 'subscribed', 'unsubscribed'));
ALTER TABLE "consent_states" ADD CONSTRAINT consent_states_state_chk CHECK (state IN ('pending', 'granted', 'withdrawn'));
ALTER TABLE "consent_states" ADD CONSTRAINT consent_states_channel_chk CHECK (channel IN ('email', 'sms', 'whatsapp'));
ALTER TABLE "consent_states" ADD CONSTRAINT consent_states_changed_by_chk CHECK (changed_by IN ('contact', 'user', 'system'));
ALTER TABLE "consent_retention_policies" ADD CONSTRAINT consent_retention_days_chk CHECK (
  (retain_after_withdrawal_days IS NULL OR retain_after_withdrawal_days >= 0)
  AND (retain_after_erasure_days IS NULL OR retain_after_erasure_days >= 0)
  AND pending_expiry_days BETWEEN 1 AND 365);
ALTER TABLE "suppressions" ADD CONSTRAINT suppressions_channel_chk CHECK (channel IN ('email', 'sms', 'whatsapp', 'all'));
ALTER TABLE "suppressions" ADD CONSTRAINT suppressions_reason_chk CHECK (reason IN ('manual', 'hard_bounce', 'complaint', 'compliance', 'unsubscribe_request', 'invalid_address'));
ALTER TABLE "suppressions" ADD CONSTRAINT suppressions_source_chk CHECK (source IN ('admin', 'import', 'system', 'api'));
-- Target is a contact XOR an address; an address always has its kind.
ALTER TABLE "suppressions" ADD CONSTRAINT suppressions_target_chk CHECK (
  (contact_id IS NULL) <> (value_normalized IS NULL) AND (value_normalized IS NULL) = (identity_kind IS NULL));
ALTER TABLE "suppressions" ADD CONSTRAINT suppressions_active_chk CHECK ((lifted_at IS NULL) = (active_key IS NOT NULL));
ALTER TABLE "contact_imports" ADD CONSTRAINT contact_imports_status_chk CHECK (status IN ('uploaded', 'validated', 'processing', 'completed', 'failed', 'cancelled'));
ALTER TABLE "contact_import_issues" ADD CONSTRAINT import_issues_severity_chk CHECK (severity IN ('error', 'warning'));
ALTER TABLE "contact_import_issues" ADD CONSTRAINT import_issues_phase_chk CHECK (phase IN ('dry_run', 'run'));

-- ─── 2. Append-only consent evidence (UPDATE blocked even for the owner; DELETE only via the retention purge) ─
CREATE TRIGGER consent_events_append_only BEFORE UPDATE ON "consent_events" FOR EACH ROW EXECUTE FUNCTION app.reject_update();

-- ─── 3. Privileges for workeasy_app (column-level UPDATE; ids and tenant keys never updatable) ─────────────────
GRANT SELECT, INSERT ON "contacts" TO workeasy_app;
GRANT UPDATE (first_name, last_name, company, timezone, locale, subscription_type, subscription_changed_at, unsubscribed_by,
              custom_fields, search_text, updated_at, deleted_at, erased_at, version) ON "contacts" TO workeasy_app;

GRANT SELECT, INSERT, DELETE ON "contact_identities" TO workeasy_app;
GRANT UPDATE (is_primary, verified_at) ON "contact_identities" TO workeasy_app;

GRANT SELECT, INSERT, DELETE ON "custom_field_definitions" TO workeasy_app;
GRANT UPDATE (key, label, description, type, required, options, validation, position, status, key_locked, updated_at, version)
  ON "custom_field_definitions" TO workeasy_app;

GRANT SELECT, INSERT ON "lists" TO workeasy_app;
GRANT UPDATE (name, name_key, description, status, updated_at, deleted_at, version) ON "lists" TO workeasy_app;
GRANT SELECT, INSERT, DELETE ON "list_memberships" TO workeasy_app;

GRANT SELECT, INSERT ON "tags" TO workeasy_app;
GRANT UPDATE (name, name_key, description, color, updated_at, deleted_at, version) ON "tags" TO workeasy_app;
GRANT SELECT, INSERT, DELETE ON "contact_tags" TO workeasy_app;

-- Topic keys are immutable (campaigns and consent evidence reference them).
GRANT SELECT, INSERT ON "topics" TO workeasy_app;
GRANT UPDATE (parent_id, name, description, status, is_default, position, updated_at, version) ON "topics" TO workeasy_app;
GRANT SELECT, INSERT ON "contact_topic_preferences" TO workeasy_app;
GRANT UPDATE (status, changed_by, last_event_id, changed_at) ON "contact_topic_preferences" TO workeasy_app;

GRANT SELECT, INSERT ON "consent_events" TO workeasy_app;           -- append-only evidence
GRANT SELECT, INSERT ON "consent_states" TO workeasy_app;
GRANT UPDATE (state, changed_by, lawful_basis, last_event_id, changed_at) ON "consent_states" TO workeasy_app;
GRANT SELECT, INSERT ON "consent_retention_policies" TO workeasy_app;
GRANT UPDATE (retain_after_withdrawal_days, retain_after_erasure_days, pending_expiry_days, updated_by_user_id, updated_at, version)
  ON "consent_retention_policies" TO workeasy_app;

-- Suppressions are never deleted; only the lifting columns can change.
GRANT SELECT, INSERT ON "suppressions" TO workeasy_app;
GRANT UPDATE (active_key, lifted_at, lifted_by_user_id, lift_reason) ON "suppressions" TO workeasy_app;

GRANT SELECT, INSERT ON "contact_imports" TO workeasy_app;
GRANT UPDATE (status, delimiter, headers, mapping, options, total_rows, processed_rows, created_count, updated_count,
              skipped_count, error_count, dry_run_summary, failure_reason, updated_at, started_at, completed_at, version)
  ON "contact_imports" TO workeasy_app;
GRANT SELECT, INSERT, DELETE ON "contact_import_issues" TO workeasy_app;

-- ─── 4. Row-level security: workspace-owned (org AND workspace must match the context) ─────────────────────────
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['contacts', 'contact_identities', 'custom_field_definitions', 'lists', 'list_memberships',
                           'tags', 'contact_tags', 'topics', 'contact_topic_preferences', 'consent_events',
                           'consent_states', 'consent_retention_policies', 'suppressions', 'contact_imports',
                           'contact_import_issues']
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR ALL
         USING (org_id = app.current_org_id() AND workspace_id = app.current_workspace_id())
         WITH CHECK (org_id = app.current_org_id() AND workspace_id = app.current_workspace_id())',
      t || '_workspace', t);
  END LOOP;
END $$;

-- Domain events: an organization-level context sees the whole organization; a workspace context sees only its own
-- workspace's events plus organization-level ones (workspace_id NULL). Tightens the Phase 4 policy.
DROP POLICY domain_events_tenant ON "domain_events";
CREATE POLICY domain_events_tenant ON "domain_events" FOR ALL
  USING (org_id = app.current_org_id()
         AND (app.current_workspace_id() IS NULL OR workspace_id IS NULL OR workspace_id = app.current_workspace_id()))
  WITH CHECK (org_id = app.current_org_id()
              AND (app.current_workspace_id() IS NULL OR workspace_id IS NULL OR workspace_id = app.current_workspace_id()));

-- ─── 5. Default "Marketing" topic for every existing workspace (new ones get it at creation) ───────────────────
INSERT INTO topics (id, org_id, workspace_id, kind, key, name, description, is_default, position)
SELECT gen_random_uuid(), w.org_id, w.id, 'topic', 'marketing', 'Marketing', 'General marketing communication', true, 0
FROM workspaces w
WHERE NOT EXISTS (SELECT 1 FROM topics t WHERE t.workspace_id = w.id AND t.key = 'marketing');

-- ─── 6. Consent-evidence retention purge (docs/consent.md §Retention) ──────────────────────────────────────────
-- SECURITY DEFINER because the runtime role cannot DELETE evidence. Callable only for the caller's OWN workspace
-- context, and deletes only rows past the policy (defaults: 2190 days ≈ 6 years; NULL policy value = keep).
CREATE FUNCTION app.purge_consent_evidence(p_workspace_id uuid)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_withdrawal int;
  v_erasure int;
  v_deleted int;
BEGIN
  IF p_workspace_id IS NULL OR p_workspace_id IS DISTINCT FROM app.current_workspace_id() THEN
    RAISE EXCEPTION 'purge is only allowed for the current workspace context' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT p.retain_after_withdrawal_days, p.retain_after_erasure_days INTO v_withdrawal, v_erasure
  FROM consent_retention_policies p WHERE p.workspace_id = p_workspace_id;
  IF NOT FOUND THEN
    v_withdrawal := 2190;
    v_erasure := 2190;
  END IF;

  DELETE FROM consent_events e
  WHERE e.workspace_id = p_workspace_id
    AND (
      (v_erasure IS NOT NULL AND EXISTS (
         SELECT 1 FROM contacts c WHERE c.id = e.contact_id AND c.erased_at < now() - make_interval(days => v_erasure)))
      OR (v_withdrawal IS NOT NULL AND e.channel IS NOT NULL AND EXISTS (
         SELECT 1 FROM consent_states s
         WHERE s.contact_id = e.contact_id AND s.channel = e.channel AND s.state = 'withdrawn'
           AND s.changed_at < now() - make_interval(days => v_withdrawal)))
      OR (v_withdrawal IS NOT NULL AND e.topic_id IS NOT NULL AND EXISTS (
         SELECT 1 FROM contact_topic_preferences tp
         WHERE tp.contact_id = e.contact_id AND tp.topic_id = e.topic_id AND tp.status = 'unsubscribed'
           AND tp.changed_at < now() - make_interval(days => v_withdrawal)))
    );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END $$;

REVOKE ALL ON FUNCTION app.purge_consent_evidence(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.purge_consent_evidence(uuid) TO workeasy_app;

-- ─── 7. Contact search (trigram index under RLS) ──────────────────────────────────────────────────────────────
-- ILIKE is not LEAKPROOF, so with RLS active PostgreSQL will not use the trigram index for it (it would scan every
-- row). This definer function performs the indexed match but filters to the CALLER'S CURRENT org + workspace itself,
-- escapes LIKE wildcards in the input, and returns ids only; callers then load rows under normal RLS.
-- Returns at most p_limit candidates, newest first (the API reports when the cap is reached).
CREATE FUNCTION app.search_contact_ids(p_query text, p_limit integer)
RETURNS TABLE (contact_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT c.id FROM contacts c
  WHERE c.org_id = app.current_org_id()
    AND c.workspace_id = app.current_workspace_id()
    AND c.erased_at IS NULL
    AND length(p_query) >= 2
    -- '!' is the escape character, so user input such as "%" or "_" matches literally.
    AND c.search_text ILIKE '%' || replace(replace(replace(lower(p_query), '!', '!!'), '%', '!%'), '_', '!_') || '%' ESCAPE '!'
  ORDER BY c.created_at DESC, c.id DESC
  LIMIT least(greatest(p_limit, 1), 5000)
$$;
REVOKE ALL ON FUNCTION app.search_contact_ids(text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.search_contact_ids(text, integer) TO workeasy_app;
